-- Batch 02: independently cross-checked public building sources. Two current evidence rows per field, one audit and one evidence group.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v5';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; sub_batch int:=2; expected_before int:=22; expected_added int:=20;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v5_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($ext$[{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"building_height","type":"numeric","value":183,"unit":"m","sources":[{"url":"https://www.skyscrapercenter.com/building/jing-cheng-dasha/2184","name":"CTBUH高层建筑数据库 Capital Mansion","tier":"authoritative_secondary"},{"url":"https://zh.wikipedia.org/wiki/%E4%BA%AC%E5%9F%8E%E5%A4%A7%E5%8E%A6_%28%E5%8C%97%E4%BA%AC%29","name":"京城大厦资料（引北京市建筑工程总公司志）","tier":"secondary"}],"note":"CTBUH列183m；历史文献转述183.35m，按两源共同支持的整米精度记录；竣工年份存在冲突，未填日期。"},{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"facade_type","type":"text","value":"花岗岩石材幕墙","unit":"configuration","sources":[{"url":"https://www.jingchengdasha.cn/index.html","name":"北京写字楼信息网－京城大厦","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/455.html","name":"明德房产楼宇参数","tier":"secondary"}],"note":"新源南路6号；两站分别注明花岗石外墙与花岗岩石材幕墙。"},{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"parking_above","type":"integer","value":122,"unit":"count","sources":[{"url":"https://www.jingchengdasha.cn/index.html","name":"北京写字楼信息网－京城大厦","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/455.html","name":"明德房产楼宇参数","tier":"secondary"}],"note":"新源南路6号同一项目；两站均列地上122；为公开招商历史参数，不声称现场复测。"},{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"parking_underground","type":"integer","value":300,"unit":"count","sources":[{"url":"https://www.jingchengdasha.cn/index.html","name":"北京写字楼信息网－京城大厦","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/455.html","name":"明德房产楼宇参数","tier":"secondary"}],"note":"新源南路6号同一项目；两站均列地下300；为公开招商历史参数，不声称现场复测。"},{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"parking_total","type":"integer","value":422,"unit":"count","sources":[{"url":"https://www.jingchengdasha.cn/index.html","name":"北京写字楼信息网－京城大厦","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/455.html","name":"明德房产楼宇参数","tier":"secondary"}],"note":"新源南路6号同一项目；明德列总数422；另一站地上122加地下300亦为422；为公开招商历史参数，不声称现场复测。"},{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"elevator_passenger","type":"integer","value":6,"unit":"count","sources":[{"url":"https://www.jingchengdasha.cn/index.html","name":"北京写字楼信息网－京城大厦","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/455.html","name":"明德房产楼宇参数","tier":"secondary"}],"note":"新源南路6号同一项目；两站均列6部客梯；为公开招商历史参数，不声称现场复测。"},{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"elevator_freight","type":"integer","value":2,"unit":"count","sources":[{"url":"https://www.jingchengdasha.cn/index.html","name":"北京写字楼信息网－京城大厦","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/455.html","name":"明德房产楼宇参数","tier":"secondary"}],"note":"新源南路6号同一项目；两站均列2部货梯；为公开招商历史参数，不声称现场复测。"},{"id":"0e2548ad-785f-4769-b034-df7ff87180f6","f":"metro_access","type":"text","value":"地铁10号线亮马桥站","unit":"nearby_station","sources":[{"url":"https://www.jingchengdasha.cn/index.html","name":"北京写字楼信息网－京城大厦","tier":"secondary"},{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=13&id=842&m=content","name":"北京写字楼招商资讯","tier":"secondary"}],"note":"两来源明确同一项目及亮马桥站；未填步行距离。"},{"id":"f470952d-6add-4151-af47-4989f1bf6e6f","f":"gfa_total","type":"numeric","value":33745.6,"unit":"m2","sources":[{"url":"https://www.bjhhsy.cn/index.html","name":"北京写字楼信息平台－海航实业大厦","tier":"secondary"},{"url":"https://office-beijing.com/office/1653.html","name":"北京写字楼门户－原丰树/摩托罗拉大厦","tier":"secondary"}],"note":"建国路108号原丰树/摩托罗拉大厦；33745.64与33745.6按共同支持一位小数；非可租面积。"},{"id":"f470952d-6add-4151-af47-4989f1bf6e6f","f":"standard_floor_area","type":"numeric","value":1889,"unit":"m2","sources":[{"url":"https://www.bjhhsy.cn/index.html","name":"北京写字楼信息平台－海航实业大厦","tier":"secondary"},{"url":"https://office-beijing.com/office/1653.html","name":"北京写字楼门户－原丰树/摩托罗拉大厦","tier":"secondary"}],"note":"两资料同列标准层1889㎡；采用整平方米。"},{"id":"f470952d-6add-4151-af47-4989f1bf6e6f","f":"efficiency_rate","type":"numeric","value":70,"unit":"percent","sources":[{"url":"https://www.bjhhsy.cn/index.html","name":"北京写字楼信息平台－海航实业大厦","tier":"secondary"},{"url":"https://office-beijing.com/office/1653.html","name":"北京写字楼门户－原丰树/摩托罗拉大厦","tier":"secondary"}],"note":"两来源同列70%使用率；历史招商口径。"},{"id":"f470952d-6add-4151-af47-4989f1bf6e6f","f":"elevator_passenger","type":"integer","value":6,"unit":"count","sources":[{"url":"https://www.bjhhsy.cn/index.html","name":"北京写字楼信息平台－海航实业大厦","tier":"secondary"},{"url":"https://office-beijing.com/office/1653.html","name":"北京写字楼门户－原丰树/摩托罗拉大厦","tier":"secondary"}],"note":"两来源同列6部办公客梯；货梯及地库客梯口径冲突，未填。"},{"id":"13e910bd-1e89-447c-a249-75e480347525","f":"gfa_total","type":"numeric","value":600000,"unit":"m2","sources":[{"url":"https://www.bjft.gov.cn/ftq/kjzyswly/202505/a33d86b6d27e452a86695a6b0bfa0192.shtml","name":"北京市丰台区政府商务楼宇资料","tier":"primary"},{"url":"https://www.fffzu.com/50/","name":"北京办公选址楼宇参数","tier":"secondary"}],"note":"丰台南四环西路186号整个园区，政府描述逾60万、目录60万；公开招商一致，约数，不拆分单栋。"},{"id":"13e910bd-1e89-447c-a249-75e480347525","f":"parking_total","type":"integer","value":3000,"unit":"count","sources":[{"url":"https://www.bjft.gov.cn/ftq/kjzyswly/202505/a33d86b6d27e452a86695a6b0bfa0192.shtml","name":"北京市丰台区政府商务楼宇资料","tier":"primary"},{"url":"https://www.fffzu.com/50/","name":"北京办公选址楼宇参数","tier":"secondary"}],"note":"园区项目总量，政府表3000、正文3000余；公开招商3000；记录约数，非单栋及地下专属数。"},{"id":"13e910bd-1e89-447c-a249-75e480347525","f":"metro_access","type":"text","value":"地铁9号线丰台科技园站上盖","unit":"nearby_station","sources":[{"url":"https://www.bjft.gov.cn/ftq/kjzyswly/202505/a33d86b6d27e452a86695a6b0bfa0192.shtml","name":"北京市丰台区政府商务楼宇资料","tier":"primary"},{"url":"https://www.hanweigj.cn/chuzu.html","name":"汉威国际广场项目招商资料","tier":"secondary"}],"note":"政府及项目招商资料均明确地铁9号线丰台科技园站与园区衔接；不填距离。"},{"id":"fda88bb5-054f-4756-9c36-cc795a92d07a","f":"developer","type":"text","value":"北京濠江房地产开发有限公司","unit":"company","sources":[{"url":"https://www.aomenzhongxin.cn/index.html","name":"北京写字楼信息网－澳门中心","tier":"secondary"},{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=604&m=content","name":"北京写字楼招商资讯－澳门中心","tier":"secondary"}],"note":"王府井东街8号同址；两来源均明确开发商名称。"},{"id":"fda88bb5-054f-4756-9c36-cc795a92d07a","f":"floor_height","type":"numeric","value":3,"unit":"m","sources":[{"url":"https://www.aomenzhongxin.cn/index.html","name":"北京写字楼信息网－澳门中心","tier":"secondary"},{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=604&m=content","name":"北京写字楼招商资讯－澳门中心","tier":"secondary"}],"note":"同址、办公区层高均为3米；净高数据不一致，未填。"},{"id":"fda88bb5-054f-4756-9c36-cc795a92d07a","f":"floors_above","type":"integer","value":14,"unit":"floor","sources":[{"url":"https://www.aomenzhongxin.cn/index.html","name":"北京写字楼信息网－澳门中心","tier":"secondary"},{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=604&m=content","name":"北京写字楼招商资讯－澳门中心","tier":"secondary"}],"note":"同址；两来源均明确地上14层。"},{"id":"fda88bb5-054f-4756-9c36-cc795a92d07a","f":"floors_below","type":"integer","value":3,"unit":"floor","sources":[{"url":"https://www.aomenzhongxin.cn/index.html","name":"北京写字楼信息网－澳门中心","tier":"secondary"},{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=604&m=content","name":"北京写字楼招商资讯－澳门中心","tier":"secondary"}],"note":"一源明确地下3层，另一源地上14/总17层，差值3。"},{"id":"2f1aec9e-4efe-441c-90eb-05fffb79ced7","f":"floors_above","type":"integer","value":17,"unit":"floor","sources":[{"url":"https://esf.fang.com/loupan/office/1010127119/housedetail.htm","name":"房天下中融信托大厦楼盘资料","tier":"secondary"},{"url":"https://www.wf-hlw.cn/","name":"北京写字楼信息平台－中融信托大厦","tier":"secondary"}],"note":"菜市口大街1号院2号，房天下明确地上17层，另一来源描述办公楼17层；不将19层总数混为地上。"}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text)) SELECT b.id bid,b.name,d.id target_id,v.f field_name,v.value new_value,v.type value_type,v.unit,v.sources,v.note FROM specs v JOIN building_brochure_data d ON d.id=v.id JOIN buildings b ON b.id=d.building_id WHERE b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.project_type='stock' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data q WHERE q.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND (SELECT count(distinct substring(s->>'url' from 'https?://([^/]+)')) FROM jsonb_array_elements(v.sources) s)>=2 AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=b.id AND p.target_table='building_brochure_data' AND p.field_name=v.f) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=d.id::text AND (a.details->>'field_name'=v.f OR a.new_values ? v.f)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_url,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  SELECT r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'internet',e->>'tier',e->>'name',e->>'url',now_ts,now_ts,'cross_verified',ev,'batch_ref=ai_building_field_backfill_20261125_v5_100; unit='||r.unit||'; '||r.note||'; AI-assisted',true FROM jsonb_array_elements(r.sources) e;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>jsonb_array_length(r.sources) OR changed<2 THEN RAISE EXCEPTION 'source count mismatch'; END IF;
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v5_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_kind','external_cross_verified','source_urls',r.sources,'unit',r.unit,'verification_status','cross_verified','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value)<>jsonb_array_length(r.sources) OR NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.event_id='ai_field_fill:'||ev::text AND a.new_values->r.field_name=read_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected %, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
COMMIT;